#!/bin/bash
# Note: files matching lib/l10n/app_localizations*.dart are excluded
# because they are auto-generated by flutter gen-l10n and contain
# framework-injected // ignore: comments without inline reasons.
# CI-014 — لا print في lib/ أو test/، ولا // ignore بلا سبب مكتوب.
FAIL=0
if grep -rn "print(" lib/ test/ 2>/dev/null; then
  echo "FAIL: print() found in lib/ or test/"
  FAIL=1
fi
# Check ignore (both // ignore: and // ignore_for_file:)
# Must match: // ignore(_for_file)?: rule1, rule2 // reason or — reason
while IFS= read -r line; do
  if ! printf '%s' "$line" | grep -qE '//\s*ignore(_for_file)?:\s*[a-zA-Z0-9_,\s]+\s*(//|—|--).+'; then
    echo "FAIL: ignore without reason: $line"
    FAIL=1
  fi
done < <(grep -rn "// ignore" lib/ test/ 2>/dev/null | grep -v "lib/l10n/app_localizations" || true)
if [ "$FAIL" -eq 0 ]; then
  echo "OK: no print / undocumented ignore"
fi
exit "$FAIL"
